<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, apiPage, mutation } from '../api/client'
import RunPanel from '../components/RunPanel.vue'
import CodeQuote from '../components/CodeQuote.vue'
type Objective={objective_version_id:string;goal_version_id:string;title:string;criteria:{criterion_version_id:string}[]}
type Catalog={github_url:string;requested_ref:string;coverage:string}
type Card={recommendation_id:string;repository_snapshot_id:string;objective_version_ids:string[];commit:string;match_level:string;reading_scope:string[];unknowns:string[];code_evidence:{path:string;symbol:string;citation_id:string}[]}
type Selection={selection_id:string;objective_version_ids:string[];repository_snapshot_id:string}
type Unit={learning_unit_id:string;selection_id:string;objective_version_id:string;criterion_version_ids:string[];commit:string;why_this_unit:string;reading_steps:{step_id:string;title:string;why:string;questions:string[];citation_ids:string[]}[];understanding_questions:string[];unknowns:string[];citations:string[];experiment:{instruction:string};task_drafts:{task_draft_id:string;title:string}[];progress:{version:number;completed_step_ids:string[];actual_minutes:number|null;note:string};needs_review:boolean;question_response?:{question:string;answer:string};feedback:{feedback_id:string}[]}
const objectives=ref<Objective[]>([]),catalog=ref<Catalog|null>(null),objectiveId=ref(''),cards=ref<Card[]>([]),selections=ref<Selection[]>([]),units=ref<Unit[]>([]),unit=ref<Unit|null>(null),runId=ref(''),selectionId=ref(''),citationId=ref(''),question=ref(''),feedbackText=ref(''),reason=ref(''),knowledge=ref(''),busy=ref(false)
const completed=ref<string[]>([]),minutes=ref<number|null>(null),note=ref('')
const write=mutation()
async function all<T>(path:string):Promise<T[]>{const rows:T[]=[];let cursor:string|null=null;do{const page:{data:T[];next_cursor?:string|null}=await apiPage<T>(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+cursor:''));rows.push(...page.data);cursor=page.next_cursor??null}while(cursor);return rows}
async function load(){try{objectives.value=await all('/learning-objectives');if(!objectiveId.value)objectiveId.value=objectives.value[0]?.objective_version_id??'';catalog.value=(await api<Catalog[]>('/repository-catalog'))[0]??null;cards.value=await all('/project-recommendations');selections.value=await all('/project-selections');units.value=await all('/learning-units')}catch(e){ElMessage.error(String(e))}}
async function research(){if(!catalog.value)return;busy.value=true;try{const repo=await write<{repository_id:string}>('/repositories','POST',{github_url:catalog.value.github_url,requested_ref:catalog.value.requested_ref});const run=await write<{run_id:string}>('/project-research-runs','POST',{objective_version_ids:[objectiveId.value],candidate_repository_ids:[repo.repository_id]});runId.value=run.run_id}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
async function selectCard(card:Card){try{const obj=objectives.value.find(o=>o.objective_version_id===objectiveId.value)||objectives.value.find(o=>card.objective_version_ids.includes(o.objective_version_id));if(!obj)return;const selected=await write<Selection>('/project-selections','POST',{recommendation_id:card.recommendation_id,objective_version_ids:[obj.objective_version_id],expected_goal_version_id:obj.goal_version_id});selectionId.value=selected.selection_id;objectiveId.value=obj.objective_version_id;await load();ElMessage.success('已保存固定版本选择，请核对后生成学习单元。')}catch(e){ElMessage.error(String(e))}}
async function reject(card:Card){if(!reason.value){ElMessage.warning('请填写拒绝理由');return}try{await write('/project-recommendations/'+card.recommendation_id+'/feedback','POST',{action:'rejected',reason_type:'other',reason:reason.value});ElMessage.success('已保存反馈；重新调研需主动发起。')}catch(e){ElMessage.error(String(e))}}
async function learn(previous=false){try{const selected=selections.value.find(s=>s.selection_id===selectionId.value);const obj=objectives.value.find(o=>o.objective_version_id===objectiveId.value);if(!selected||!obj){ElMessage.warning('请选择目标与参考版本');return}const run=await write<{run_id:string}>('/learning-path-runs','POST',{selection_id:selected.selection_id,objective_version_ids:[obj.objective_version_id],criterion_version_ids:obj.criteria.map(c=>c.criterion_version_id),user_prior_knowledge:knowledge.value,...(previous&&unit.value?{previous_learning_unit_id:unit.value.learning_unit_id,feedback_ids:unit.value.feedback.map(f=>f.feedback_id)}:{})});runId.value=run.run_id}catch(e){ElMessage.error(String(e))}}
async function progress(){await load();try{const run=await api<{output_refs:{learning_unit_id?:string}[]}>(`/runs/${runId.value}`);const id=run.output_refs.find(x=>x.learning_unit_id)?.learning_unit_id;if(id)openUnit(await api<Unit>('/learning-units/'+id))}catch(e){ElMessage.error(String(e))}}
function openUnit(row:Unit){unit.value=row;selectionId.value=row.selection_id;objectiveId.value=row.objective_version_id;completed.value=[...row.progress.completed_step_ids];minutes.value=row.progress.actual_minutes;note.value=row.progress.note;citationId.value=row.citations[0]??''}
async function saveProgress(){if(!unit.value)return;try{await write('/learning-units/'+unit.value.learning_unit_id+'/progress','PATCH',{expected_version:unit.value.progress.version,completed_step_ids:completed.value,actual_minutes:minutes.value,note:note.value});openUnit(await api<Unit>('/learning-units/'+unit.value.learning_unit_id));ElMessage.success('已记录阅读进度，能力状态未变化。')}catch(e){ElMessage.error(String(e))}}
async function ask(){if(!unit.value)return;try{const run=await write<{run_id:string}>('/learning-units/'+unit.value.learning_unit_id+'/questions','POST',{question:question.value});runId.value=run.run_id}catch(e){ElMessage.error(String(e))}}
async function feedback(){if(!unit.value)return;try{await write('/learning-units/'+unit.value.learning_unit_id+'/feedback','POST',{kind:'explanation_error',detail:feedbackText.value,citation_ids:citationId.value?[citationId.value]:[]});openUnit(await api<Unit>('/learning-units/'+unit.value.learning_unit_id));ElMessage.success('已保留纠错意见；旧单元不变。')}catch(e){ElMessage.error(String(e))}}
onMounted(load)
</script>
<template>
<section class="page-heading"><div><span class="eyebrow">参考实现 → 阅读 → 本人迁移</span><h1>项目与代码学习</h1><p>固定版本、原文引用。阅读进度与能力验收分别记录。</p></div><el-button @click="load">刷新</el-button></section>
<el-alert title="离线模式只读取已保存的公开文本；完整入口、测试与运行行为可能未知。参考仓库不会作为平台运行依赖。" :closable="false"/>
<section class="table-card panel"><h2>选择目标和参考材料</h2><el-select v-model="objectiveId" placeholder="学习目标"><el-option v-for="o in objectives" :key="o.objective_version_id" :label="o.title" :value="o.objective_version_id"/></el-select><p v-if="catalog">{{catalog.github_url}}<br><small>{{catalog.requested_ref}} · {{catalog.coverage}}</small></p><el-button type="primary" :disabled="!objectiveId" :loading="busy" @click="research">核查已保存的参考版本</el-button></section>
<RunPanel v-if="runId" :key="runId" :run-id="runId" @changed="progress"/>
<section v-for="c in cards" :key="c.recommendation_id" class="table-card panel"><h2>参考候选 · 适用性待确认</h2><small>{{c.commit}}</small><p v-for="u in c.unknowns" :key="u">{{u}}</p><el-button v-for="e in c.code_evidence" :key="e.citation_id" link @click="citationId=e.citation_id">{{e.symbol}}</el-button><p><el-button type="primary" @click="selectCard(c)">选择此固定版本</el-button></p><el-input v-model="reason" placeholder="难度、资源或兴趣方面的拒绝理由"/><el-button link @click="reject(c)">保存拒绝反馈</el-button></section>
<section class="table-card panel"><h2>生成学习单元</h2><el-select v-model="selectionId" placeholder="已保存的项目选择"><el-option v-for="s in selections" :key="s.selection_id" :label="'参考选择 '+s.selection_id.slice(0,8)" :value="s.selection_id"/></el-select><p><el-input v-model="knowledge" type="textarea" placeholder="已有知识和希望核对的范围（可空）"/></p><el-button type="primary" :disabled="!selectionId" @click="learn()">生成离线阅读单元</el-button></section>
<CodeQuote v-if="citationId" :citation-id="citationId"/>
<section class="table-card panel"><h2>已保存的学习单元</h2><el-button v-for="u in units" :key="u.learning_unit_id" @click="openUnit(u)">{{u.why_this_unit}} · {{u.learning_unit_id.slice(0,6)}}</el-button></section>
<section v-if="unit" class="table-card panel"><h2>{{unit.why_this_unit}}</h2><small>commit {{unit.commit}}</small><el-alert v-if="unit.needs_review" title="此单元存在待复核反馈" type="warning" :closable="false"/><el-checkbox-group v-model="completed"><div v-for="s in unit.reading_steps" :key="s.step_id"><el-checkbox :value="s.step_id">{{s.title}}</el-checkbox><p>{{s.why}}</p><p v-for="q in s.questions" :key="q">{{q}}</p><el-button v-for="id in s.citation_ids" :key="id" link @click="citationId=id">查看原始代码引用</el-button></div></el-checkbox-group><h3>理解问题</h3><p v-for="q in unit.understanding_questions" :key="q">{{q}}</p><h3>小实验</h3><p>{{unit.experiment.instruction}}</p><p v-for="u in unit.unknowns" :key="u">待验证：{{u}}</p><el-input-number v-model="minutes" :min="0" placeholder="实际分钟"/><el-input v-model="note" placeholder="阅读笔记"/><el-button @click="saveProgress">保存阅读进度</el-button><h3>追问与纠错</h3><el-input v-model="question" placeholder="对当前固定文本提问"/><el-button @click="ask">发起有界追问</el-button><p v-if="unit.question_response">{{unit.question_response.answer}}</p><el-input v-model="feedbackText" type="textarea" placeholder="说明引用、解释或范围问题"/><el-button @click="feedback">保存纠错意见</el-button><el-button :disabled="!selectionId" @click="learn(true)">根据反馈生成新单元</el-button><h3>任务草稿</h3><p v-for="d in unit.task_drafts" :key="d.task_draft_id">{{d.title}}</p><router-link to="/build">在自主构建中核对并物化草稿 →</router-link></section>
</template>
<style scoped>.panel{padding:24px;margin:20px 0}.panel .el-select{min-width:280px;max-width:100%}.panel .el-input{margin:8px 0}</style>
